mapper.select:
select r.id, a.patient_name as patientName, a.gender, timestampdiff(year,a.birth_date,now()) as age, concat(substring(a.id_card_no,1,3),"***********",substring(a.id_card_no,15,4)) as idCardNo, a.phone, concat(substring(a.phone,1,3),"****",substring(a.phone,8,4)) as hidePhone, a.address, a.appointment_date as appointmentDate, r.status, r.file_url as fileUrl, r.express_no as expressNo, r.express_date as expressDate from med_exam_report r join med_exam_appointment a on r.appointment_id = a.id
and a.patient_name like concat("%",#{patientName},"%")
and a.phone = #{phone}
and r.express_no = #{expressNo}
and r.status = #{status}
order by r.id desc limit #{startIndex}, #{pageSize}

select count(*) from med_exam_report r join med_exam_appointment a on r.appointment_id = a.id
and a.patient_name like concat("%",#{patientName},"%")
and a.phone = #{phone}
and r.express_no = #{expressNo}
and r.status = #{status}
